import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

export default function Maintenance() {
    const [activeTab, setActiveTab] = useState('archive');
    const [availablePIDs, setAvailablePIDs] = useState([]);
    const [selectedPIDsForSearch, setSelectedPIDsForSearch] = useState([]);
    const [matchingLogs, setMatchingLogs] = useState([]);
    const [selectedLogs, setSelectedLogs] = useState([]);
    const [columnStats, setColumnStats] = useState([]);
    const [selectedPIDs, setSelectedPIDs] = useState([]);
    const [loading, setLoading] = useState(false);
    const [status, setStatus] = useState('');
    const [pidSearchTerm, setPidSearchTerm] = useState('');

    const fetchAvailablePIDs = useCallback(async () => {
        try {
            const response = await axios.get('/api/maintenance/available-pids');
            setAvailablePIDs(response.data);
        } catch (error) {
            console.error("Error fetching available PIDs:", error);
        }
    }, []);

    const fetchColumnStats = useCallback(async () => {
        setLoading(true);
        setStatus('');
        try {
            const response = await axios.get('/api/maintenance/column-stats');
            setColumnStats(response.data);
        } catch (error) {
            console.error("Error fetching column stats:", error);
            setStatus('Error loading PID statistics.');
        }
        setLoading(false);
    }, []);

    useEffect(() => {
        fetchAvailablePIDs();
        if (activeTab === 'pids') {
            fetchColumnStats();
        }
    }, [activeTab, fetchColumnStats, fetchAvailablePIDs]);

    const handleLogSearch = async () => {
        if (selectedPIDsForSearch.length === 0) {
            setStatus('Please select at least one PID to search for.');
            return;
        }
        setLoading(true);
        setStatus('');
        try {
            const response = await axios.post('/api/maintenance/search-by-columns', { 
                column_names: selectedPIDsForSearch 
            });
            setMatchingLogs(response.data);
            setSelectedLogs([]);
            if (response.data.length === 0) setStatus('No logs found matching those columns.');
        } catch (error) {
            setStatus('Search failed.');
        }
        setLoading(false);
    };

    const togglePidSearchSelection = (pid) => {
        setSelectedPIDsForSearch(prev => 
            prev.includes(pid) ? prev.filter(p => p !== pid) : [...prev, pid]
        );
    };

    const filteredPIDs = availablePIDs.filter(pid => 
        pid.toLowerCase().includes(pidSearchTerm.toLowerCase()) && 
        !selectedPIDsForSearch.includes(pid)
    );

    const toggleLogSelection = (logId) => {
        setSelectedLogs(prev => 
            prev.includes(logId) ? prev.filter(id => id !== logId) : [...prev, logId]
        );
    };

    const executeArchive = async () => {
        if (selectedLogs.length === 0) return;
        if (!window.confirm(`Are you sure you want to delete ${selectedLogs.length} logs from the DB and move them to archive?`)) return;

        setLoading(true);
        setStatus('Archiving logs...');
        try {
            const response = await axios.post('/api/maintenance/archive-logs', { log_ids: selectedLogs });
            if (response.data.success) {
                setStatus(`Successfully processed ${response.data.results.length} logs.`);
                handleLogSearch(); // Refresh list
            }
        } catch (error) {
            setStatus('Archive failed.');
        }
        setLoading(false);
    };

    const togglePIDSelection = (pid) => {
        setSelectedPIDs(prev => 
            prev.includes(pid) ? prev.filter(p => p !== pid) : [...prev, pid]
        );
    };

    const executeBlacklist = async () => {
        if (selectedPIDs.length === 0) return;
        if (!window.confirm(`This will PERMANENTLY drop the columns [${selectedPIDs.join(', ')}] from the database and blacklist them from future ingestion. Continue?`)) return;

        setLoading(true);
        setStatus('Blacklisting PIDs...');
        try {
            const response = await axios.post('/api/maintenance/blacklist-pids', { pids: selectedPIDs });
            if (response.data.success) {
                setStatus(`Successfully blacklisted ${selectedPIDs.length} PIDs.`);
                fetchColumnStats();
                setSelectedPIDs([]);
                fetchAvailablePIDs(); // Refresh available list
            }
        } catch (error) {
            setStatus('Blacklisting failed.');
        }
        setLoading(false);
    };

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold text-cyan-400">System Maintenance</h1>

            <div className="flex space-x-4 border-b border-gray-700">
                <button 
                    onClick={() => setActiveTab('archive')}
                    className={`pb-2 px-4 font-medium transition-colors ${activeTab === 'archive' ? 'text-cyan-400 border-b-2 border-cyan-400' : 'text-gray-400 hover:text-white'}`}
                >
                    Log Purge & Archive
                </button>
                <button 
                    onClick={() => setActiveTab('pids')}
                    className={`pb-2 px-4 font-medium transition-colors ${activeTab === 'pids' ? 'text-cyan-400 border-b-2 border-cyan-400' : 'text-gray-400 hover:text-white'}`}
                >
                    PID Cleanup & Blacklist
                </button>
            </div>

            {status && (
                <div className="bg-blue-900/20 border border-blue-500 p-3 rounded text-blue-200">
                    {status}
                </div>
            )}

            {activeTab === 'archive' && (
                <div className="bg-gray-800 rounded-lg p-6 shadow-xl space-y-6">
                    <div>
                        <h2 className="text-xl font-semibold mb-2">Search Logs by Column Presence</h2>
                        <p className="text-gray-400 text-sm mb-4">Select PIDs to find logs that contain them (e.g. searching for Bank 2 sensors to find logs from other vehicles).</p>

                        <div className="space-y-4">
                            {/* Selected PIDs Tags */}
                            <div className="flex flex-wrap gap-2">
                                {selectedPIDsForSearch.map(pid => (
                                    <span key={pid} className="bg-cyan-900/50 text-cyan-200 px-3 py-1 rounded-full text-sm border border-cyan-700 flex items-center">
                                        {pid}
                                        <button onClick={() => togglePidSearchSelection(pid)} className="ml-2 hover:text-white">×</button>
                                    </span>
                                ))}
                                {selectedPIDsForSearch.length === 0 && <span className="text-gray-500 italic">No PIDs selected...</span>}
                            </div>

                            <div className="flex space-x-4">
                                <div className="relative flex-1">
                                    <input 
                                        type="text" 
                                        value={pidSearchTerm}
                                        onChange={(e) => setPidSearchTerm(e.target.value)}
                                        placeholder="Type to filter PIDs..."
                                        className="w-full bg-gray-700 border-gray-600 rounded px-4 py-2 text-white focus:ring-cyan-500"
                                    />
                                    {pidSearchTerm && (
                                        <div className="absolute z-10 w-full mt-1 bg-gray-700 border border-gray-600 rounded shadow-2xl max-h-60 overflow-y-auto">
                                            {filteredPIDs.map(pid => (
                                                <div 
                                                    key={pid} 
                                                    onClick={() => { togglePidSearchSelection(pid); setPidSearchTerm(''); }}
                                                    className="px-4 py-2 hover:bg-cyan-600 cursor-pointer text-sm"
                                                >
                                                    {pid}
                                                </div>
                                            ))}
                                            {filteredPIDs.length === 0 && <div className="px-4 py-2 text-gray-500 italic">No matching PIDs found</div>}
                                        </div>
                                    )}
                                </div>
                                <button 
                                    onClick={handleLogSearch}
                                    disabled={loading || selectedPIDsForSearch.length === 0}
                                    className="bg-cyan-600 hover:bg-cyan-700 px-8 py-2 rounded font-medium disabled:opacity-50 transition-colors"
                                >
                                    {loading ? 'Searching...' : 'Search Logs'}
                                </button>
                            </div>
                        </div>
                    </div>

                    {matchingLogs.length > 0 && (
                        <div className="space-y-4 pt-4 border-t border-gray-700">
                            <div className="flex justify-between items-center">
                                <h3 className="text-lg font-medium text-yellow-400">{matchingLogs.length} Matching Logs Found</h3>
                                <button 
                                    onClick={executeArchive}
                                    disabled={loading || selectedLogs.length === 0}
                                    className="bg-red-600 hover:bg-red-700 px-6 py-2 rounded font-medium disabled:opacity-50 transition-colors shadow-lg"
                                >
                                    Archive Selected Logs
                                </button>
                            </div>
                            <div className="max-h-96 overflow-y-auto border border-gray-700 rounded bg-gray-900/30">
                                <table className="w-full text-left">
                                    <thead className="bg-gray-900 sticky top-0">
                                        <tr>
                                            <th className="p-3 w-10">
                                                <input 
                                                    type="checkbox" 
                                                    checked={selectedLogs.length === matchingLogs.length}
                                                    onChange={() => setSelectedLogs(selectedLogs.length === matchingLogs.length ? [] : matchingLogs.map(l => l.log_id))}
                                                />
                                            </th>
                                            <th className="p-3">File Name</th>
                                            <th className="p-3">Start Time</th>
                                            <th className="p-3 text-right">Duration</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {matchingLogs.map(log => (
                                            <tr key={log.log_id} className="border-t border-gray-700 hover:bg-gray-700/50">
                                                <td className="p-3">
                                                    <input 
                                                        type="checkbox" 
                                                        checked={selectedLogs.includes(log.log_id)}
                                                        onChange={() => toggleLogSelection(log.log_id)}
                                                    />
                                                </td>
                                                <td className="p-3 font-mono text-sm">{log.file_name}</td>
                                                <td className="p-3 text-sm">
                                                    {log.start_time ? new Date(log.start_time).toLocaleString() : 'N/A'}
                                                </td>
                                                <td className="p-3 text-sm text-right">{(log.trip_duration_seconds / 60).toFixed(1)}m</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'pids' && (
                <div className="bg-gray-800 rounded-lg p-6 shadow-xl space-y-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <h2 className="text-xl font-semibold mb-2">PID Usage & Data Quality</h2>
                            <p className="text-gray-400 text-sm mb-4">Analyze which PIDs contain actual data. Rows with 0 non-zero values are likely unsupported by your vehicle.</p>
                        </div>
                        <button 
                            onClick={executeBlacklist}
                            disabled={loading || selectedPIDs.length === 0}
                            className="bg-red-600 hover:bg-red-700 px-6 py-2 rounded font-medium disabled:opacity-50 transition-colors shadow-lg"
                        >
                            Blacklist & Drop Selected
                        </button>
                    </div>

                    <div className="max-h-[600px] overflow-y-auto border border-gray-700 rounded bg-gray-900/30">
                        <table className="w-full text-left">
                            <thead className="bg-gray-900 sticky top-0">
                                <tr>
                                    <th className="p-3 w-10"></th>
                                    <th className="p-3">PID Name (Source)</th>
                                    <th className="p-3">Sanitized Name</th>
                                    <th className="p-3 text-right">Populated Rows</th>
                                    <th className="p-3 text-right">Total Rows</th>
                                    <th className="p-3 text-right">Fill %</th>
                                </tr>
                            </thead>
                            <tbody>
                                {columnStats.map(col => {
                                    const fillPct = col.total_rows > 0 ? (col.populated_rows / col.total_rows) * 100 : 0;
                                    const isEmpty = col.populated_rows === 0;

                                    return (
                                        <tr key={col.column_id} className={`border-t border-gray-700 hover:bg-gray-700/50 ${isEmpty ? 'bg-red-900/10' : ''}`}>
                                            <td className="p-3">
                                                <input 
                                                    type="checkbox" 
                                                    checked={selectedPIDs.includes(col.column_name)}
                                                    onChange={() => togglePIDSelection(col.column_name)}
                                                />
                                            </td>
                                            <td className="p-3 font-medium">{col.column_name}</td>
                                            <td className="p-3 font-mono text-xs text-gray-400">{col.sanitized_name}</td>
                                            <td className={`p-3 text-right ${isEmpty ? 'text-red-400 font-bold' : ''}`}>{col.populated_rows.toLocaleString()}</td>
                                            <td className="p-3 text-right text-gray-400">{col.total_rows.toLocaleString()}</td>
                                            <td className="p-3 text-right">
                                                <span className={`px-2 py-1 rounded text-xs ${fillPct > 50 ? 'bg-green-900/30 text-green-400' : fillPct > 0 ? 'bg-yellow-900/30 text-yellow-400' : 'bg-red-900/30 text-red-400'}`}>
                                                    {fillPct.toFixed(1)}%
                                                </span>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
}
